SELECT "Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" AS "nome_da_sit_matricula__situacao_detalhada_",   SUM(CAST("Uberlandia_1"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok" FROM "Uberlandia_1" WHERE ((NOT (("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" IN ('AGUARD_CONF', 'CANC_DESISTENTE', 'CANC_MAT_PRIM_OPCAO', 'CANC_SANÇÃO', 'CANC_SEM_FREQ_INICIAL', 'CANC_TURMA', 'DOC_INSUFIC', 'ESCOL_INSUFIC', 'INC _ITINERARIO', 'INSC_CANC', 'NÃO_COMPARECEU', 'TURMA_CANC', 'VAGAS_INSUFIC')) OR ("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND (NOT ("Uberlandia_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY "Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_";
